def components(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; comps={}
    bg=set(g[r][c] for r in range(h) for c in range(w))
    # background = most common color
    from collections import Counter
    cnt=Counter(x for r in g for x in r); bgc=cnt.most_common(1)[0][0]
    for r in range(h):
        for c in range(w):
            if not seen[r][c] and g[r][c]!=bgc:
                col=g[r][c]; stack=[(r,c)]; seen[r][c]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==col:
                                seen[ny][nx]=True; stack.append((ny,nx))
                comps.setdefault(col,[]).append(cells)
    return comps,bgc
