def transform(g):
    h,w=len(g),len(g[0])
    cd,_=components(g)
    from collections import Counter
    bgc=Counter(v for r in g for v in r).most_common(1)[0][0]
    comps=[c for col,cs in cd.items() if col!=bgc for c in cs]
    seeds=[c for c in comps if min(r for r,_ in c)>0 and max(r for r,_ in c)<h-1]
    emit=[c for c in comps if c not in seeds]
    sc=g[seeds[0][0][0]][seeds[0][0][1]]
    seedcols={cc for c in seeds for (_,cc) in c}
    smin,smax=min(seedcols),max(seedcols); span=smax-smin+1
    colsbyc={}
    for cells in emit:
        for (_,cc) in cells: colsbyc.setdefault(cc,[]).append(cells)
    out=[r[:] for r in g]
    # seeds fill toward an object aligned in their column, then become 4
    for c in seeds:
        for (r,cc) in c:
            out[r][cc]=4
            above=any(cc in colsbyc and any((rr,cc2)==(rr2,cc) for cells in colsbyc[cc] for (rr2,cc2) in cells if rr2<r) for rr in range(r))
            up=[rr for cells in colsbyc.get(cc,[]) for (rr,_) in cells if rr<r]
            dn=[rr for cells in colsbyc.get(cc,[]) for (rr,_) in cells if rr>r]
            if up and not dn: rng=range(r-1,min(up)-1,-1)
            else: rng=range(r+1,max(dn)+1 if dn else h)
            for rr in rng:
                if g[rr][cc]==bgc: out[rr][cc]=sc
                else: break
    # unaligned emitter bars paint seed color away from their edge
    for cells in emit:
        rows_=[r for r,_ in cells]; ecs=sorted(set(cc for _,cc in cells))
        top=min(rows_); bot=max(rows_)
        aligned = any(cc in seedcols for cc in ecs)
        if aligned: continue
        pint = ecs[:span] if smax < ecs[0] else ecs[-span:]
        if bot==h-1: rng=range(h-2,-1,-1); start=top  # bottom bar paints up
        else: rng=range(h-1,top,-1)
        for cc in pint:
            for rr in rng:
                if g[rr][cc]==bgc: out[rr][cc]=sc
                else: break
    return out
